/**
 * @file renderPages.js
 * @module scripts/docs/lib/renderPages
 * @summary Renders one markdown file to a full HTML page, and recursively
 * walks docs/ rendering every page it finds.
 * @enterprise Composes markedConfig (parse markdown), htmlPostprocess
 * (mermaid-wrap + link-rewrite), and tocBuilder (sidebar nav) into the
 * per-page rendering pipeline (convertMd), then drives that pipeline over
 * the whole docs/ tree (processDir). SKIP_DIRS lives here rather than in
 * the entry script because it's intrinsic to the walk itself: jsdoc/ and
 * coverage/ are generated by other tools and must never be treated as
 * markdown source.
 */
const fs   = require('fs');
const path = require('path');
const { markedFn } = require('./markedConfig');
const { wrapMermaid, rewriteLinks } = require('./htmlPostprocess');
const { buildToc } = require('./tocBuilder');

// Subdirectories inside docs/ that contain generated output or theme assets
// -- never walk them for markdown
const SKIP_DIRS = new Set(['jsdoc', 'coverage', '_theme']);

/**
 * @param {string} mdPath - Absolute path to the source .md file
 * @param {string} template - Assembled header+page+footer template with
 *   {{TITLE}}/{{TOC}}/{{CONTENT}} placeholders
 * @returns {string} Fully rendered HTML page
 */
function convertMd(mdPath, template) {
  const src  = fs.readFileSync(mdPath, 'utf8');
  const h1   = src.match(/^#\s+(.+)$/m);
  const title = h1 ? h1[1].trim() : path.basename(mdPath, '.md');

  let html = markedFn(src);
  html = wrapMermaid(html);
  html = rewriteLinks(html);

  // Title suffix is added here rather than in header.html so the hub can set a different title
  return template
    .replace('{{TITLE}}',   title + ' — my-portfolio docs')
    .replace('{{TOC}}',     buildToc(html))
    .replace('{{CONTENT}}', html);
}

/**
 * For pages one or more levels below docs/, rewrite the two relative hrefs
 * in header.html so the stylesheet and the hub back-link resolve correctly.
 * Depth 0 = docs/ root; depth 1 = docs/architecture/, etc.
 *
 * @param {string} template
 * @param {number} depth
 * @returns {string}
 */
function adjustTemplate(template, depth) {
  if (depth === 0) return template;
  const prefix = '../'.repeat(depth);
  return template
    .replace('href="_theme/css/styles.css"', `href="${prefix}_theme/css/styles.css"`)
    .replace('src="_theme/js/docs.js"',      `src="${prefix}_theme/js/docs.js"`)
    .replace('href="index.html"',            `href="${prefix}index.html"`);
}

/**
 * Recursively walks `dir`, converting every .md file to .html next to its
 * source and skipping SKIP_DIRS entirely.
 *
 * @param {string} dir - Directory to walk (starts at docsDir, depth 0)
 * @param {number} depth - Levels below docsDir, used to adjust relative hrefs
 * @param {string} template - Assembled page template (pre-adjustTemplate)
 * @param {string} docsDir - Root docs/ directory, used only for relative
 *   logging output
 */
function processDir(dir, depth, template, docsDir) {
  const adjusted = adjustTemplate(template, depth);
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (err) {
    console.error(`[build_docs] Cannot read ${dir}: ${err.message}`);
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name)) processDir(fullPath, depth + 1, template, docsDir);
    } else if (entry.name.endsWith('.md')) {
      // docs/index.md must not overwrite index.html — the assembled landing page owns that slot
      const baseName = (depth === 0 && entry.name === 'index.md')
        ? 'docs-index'
        : path.basename(entry.name, '.md');
      const out = path.join(dir, baseName + '.html');
      try {
        fs.writeFileSync(out, convertMd(fullPath, adjusted), 'utf8');
        const relIn  = path.relative(docsDir, fullPath);
        const relOut = path.relative(docsDir, out);
        console.log(`[build_docs]  ${relIn} → ${relOut}`);
      } catch (err) {
        console.error(`[build_docs]  FAIL ${path.relative(docsDir, fullPath)}: ${err.message}`);
      }
    }
  }
}

module.exports = { convertMd, adjustTemplate, processDir };
